import { useState } from "react";

export function CheckedState({
  label = "{{label}}",
  kind = "{{kind}}",
  accent = "{{accent}}",
  force = {{force}},
}) {
  const [checked, setChecked] = useState(force);
  return (
    <div>
      <label style={{ display: "flex", alignItems: "center", gap: 10, width: 280, boxSizing: "border-box", font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: "16px 18px", borderRadius: 12, cursor: "pointer" }}>
        <input type={kind} checked={checked} onChange={(e) => setChecked(e.target.checked)} style={{ width: 19, height: 19, accentColor: accent }} />
        <span style={{ fontWeight: checked ? 700 : 400 }}>{label}</span>
      </label>
      <p style={{ width: 280, margin: "8px 0 0", fontSize: 11, color: "#241430888" }}>Click to toggle the real <code>:checked</code> state, or force it with the <code>force</code> prop.</p>
    </div>
  );
}
